patch:
--- a/corpus/klg_l01_two_alloc.c
+++ b/corpus/klg_l01_two_alloc.c
@@ -15,8 +15,10 @@
 	if (!a)
 		return -ENOMEM;
 	b = kmalloc(200, GFP_KERNEL);	/* GT:SAFE */
-	if (!b)
+	if (!b) {
+		kfree(a);
 		return -ENOMEM;		/* a leaks here */
+	}

 	memset(a, 0, 100);
 	memset(b, 0, 200);

--- a/corpus/klg_l02_goto_ladder.c
+++ b/corpus/klg_l02_goto_ladder.c
@@ -38,6 +38,7 @@
 	name = kasprintf(GFP_KERNEL, "sensor%d", 0);	/* GT:SAFE */
 	if (!name) {
 		ret = -ENOMEM;
+		kfree(tx);
 		goto err_rx;		/* BUG: should be err_tx */
 	}

--- a/corpus/klg_l03_reg_fail.c
+++ b/corpus/klg_l03_reg_fail.c
@@ -36,8 +36,10 @@
 	ch->id = 3;

 	ret = hw_register_channel(ch);
-	if (ret)
+	if (ret) {
+		kfree(ch);
 		return ret;		/* ch leaks here */
+	}

 	ch->flags = 1;
 	hw_unregister_channel(ch);

--- a/corpus/klg_l04_loop_partial.c
+++ b/corpus/klg_l04_loop_partial.c
@@ -17,8 +17,11 @@

 	for (i = 0; i < NR_DESC; i++) {
 		desc[i] = kmalloc(DESC_SIZE, GFP_KERNEL);	/* GT:LEAK */
-		if (!desc[i])
+		if (!desc[i]) {
+			while (--i >= 0)
+				kfree(desc[i]);
 			return -ENOMEM;	/* earlier descriptors leak */
+		}
 	}

 	for (i = 0; i < NR_DESC; i++)

--- a/corpus/klg_l05_usercopy.c
+++ b/corpus/klg_l05_usercopy.c
@@ -21,8 +21,10 @@
 	if (!kbuf)
 		return -ENOMEM;

-	if (copy_from_user(kbuf, ubuf, len))
+	if (copy_from_user(kbuf, ubuf, len)) {
+		kfree(kbuf);
 		return -EFAULT;		/* kbuf leaks here */
+	}
 	kbuf[len] = '\0';

 	ret = kstrtoul(kbuf, 0, &cfg_value);

--- a/corpus/klg_l06_wrapper_alloc.c
+++ b/corpus/klg_l06_wrapper_alloc.c
@@ -39,8 +39,10 @@
 		return -ENOMEM;

 	tok = kmalloc(64, GFP_KERNEL);		/* GT:SAFE */
-	if (!tok)
+	if (!tok) {
+		session_destroy(s);
 		return -ENOMEM;		/* s leaks here */
+	}

 	strscpy(tok, "token", 64);
 	strscpy(s->tag, tok, sizeof(s->tag));

--- a/corpus/klg_l07_wrapper_free.c
+++ b/corpus/klg_l07_wrapper_free.c
@@ -29,8 +29,10 @@
 		return -ENOMEM;

 	scratch = kmalloc(1024, GFP_KERNEL);	/* GT:SAFE */
-	if (!scratch)
+	if (!scratch) {
+		ctx_release(c);
 		return -ENOMEM;		/* c leaks: ctx_release() not called */
+	}

 	memset(scratch, 0, 1024);
 	c->done = 1024;

--- a/corpus/klg_l08_kstrdup.c
+++ b/corpus/klg_l08_kstrdup.c
@@ -18,8 +18,10 @@
 		return -ENOMEM;

 	blob = kmemdup(profile_template, sizeof(profile_template), GFP_KERNEL);	/* GT:SAFE */
-	if (!blob)
+	if (!blob) {
+		kfree(label);
 		return -ENOMEM;		/* label leaks here */
+	}

 	pr_debug("profile %s: %*ph\n", label, 3, blob);
 	kfree(blob);

--- a/corpus/klg_l09_kcalloc.c
+++ b/corpus/klg_l09_kcalloc.c
@@ -21,6 +21,7 @@
 	vals = kmalloc_array(NR_KEYS, sizeof(*vals), GFP_KERNEL);	/* GT:SAFE */
 	if (!vals) {
 		ret = -ENOMEM;
+		kfree(idx);
 		goto out;		/* idx leaks: out does not free it */
 	}

--- a/corpus/klg_l10_vmalloc.c
+++ b/corpus/klg_l10_vmalloc.c
@@ -24,8 +24,10 @@
 		return -ENOMEM;

 	hdr = kzalloc(sizeof(*hdr), GFP_KERNEL);	/* GT:SAFE */
-	if (!hdr)
+	if (!hdr) {
+		vfree(fw);
 		return -ENOMEM;		/* fw leaks here */
+	}

 	memset(fw, 0, FW_SIZE);
 	hdr->magic = 0x4b4c47;

--- a/corpus/klg_l11_kmem_cache.c
+++ b/corpus/klg_l11_kmem_cache.c
@@ -24,8 +24,10 @@
 		return -ENOMEM;

 	payload = kzalloc(256, GFP_KERNEL);	/* GT:SAFE */
-	if (!payload)
+	if (!payload) {
+		kmem_cache_free(req_cache, req);
 		return -ENOMEM;		/* req leaks here */
+	}

 	req->sector = 8;
 	req->len = 256;

--- a/corpus/klg_l12_multi_exit.c
+++ b/corpus/klg_l12_multi_exit.c
@@ -23,6 +23,7 @@

 	crc = kmalloc(32, GFP_KERNEL);		/* GT:SAFE */
 	if (!crc) {
+		kfree(pkt);
 		kfree(hdr);
 		return -ENOMEM;		/* BUG: pkt is not freed */
 	}

--- a/corpus/klg_l13_init_misc.c
+++ b/corpus/klg_l13_init_misc.c
@@ -45,8 +45,10 @@
 	led_table_fill(tbl);

 	ret = misc_register(&ledctl_dev);
-	if (ret)
+	if (ret) {
+		kfree(tbl);
 		return ret;		/* tbl leaks here */
+	}

 	ledctl_tbl = tbl;
 	return 0;

--- a/corpus/klg_l14_cond_alloc.c
+++ b/corpus/klg_l14_cond_alloc.c
@@ -35,6 +35,7 @@

 	ret = stats_calibrate(samples);
 	if (ret) {
+		kfree(hist);
 		kfree(samples);
 		return ret;		/* hist leaks here */
 	}

--- a/corpus/klg_l17_local_struct.c
+++ b/corpus/klg_l17_local_struct.c
@@ -23,8 +23,10 @@
 		return -ENOMEM;

 	ws.out = kmalloc(ws.len, GFP_KERNEL);	/* GT:SAFE */
-	if (!ws.out)
+	if (!ws.out) {
+		kfree(ws.in);
 		return -ENOMEM;		/* ws.in leaks here */
+	}

 	memset(ws.in, 1, ws.len);
 	memcpy(ws.out, ws.in, ws.len);
